import React, { useEffect, useState } from "react";
import axios from "axios";

export default function UserPanel() {
  const [challans, setChallans] = useState([]);

  const loadUserChallans = async () => {
    const vehicle = localStorage.getItem("user");
    const { data } = await axios.get(`http://localhost:5000/challan/${vehicle}`);
    setChallans(data);
  };

  useEffect(() => {
    loadUserChallans();
  }, []);

  return (
    <div style={{ padding: 20 }}>
      <h2>User Challans</h2>

      {challans.map((c) => (
        <div key={c._id} style={{
          border: "1px solid #999",
          padding: 10,
          marginBottom: 10
        }}>
          <p><b>Vehicle:</b> {c.vehicleNumber}</p>
          <p><b>Cause:</b> {c.violation}</p>
          <p><b>Fine:</b> ₹{c.fineAmount}</p>
          <p><b>Date:</b> {c.dateIssued}</p>
          <p><b>Due:</b> {c.dueDate}</p>
          <p><b>Address:</b> {c.address}</p>
          <p><b>Status:</b> {c.status}</p>
        </div>
      ))}
    </div>
  );
}
